.card {
  position: relative;
  width: 300px;
  height: 400px;
  background: #111;
  border-radius: 16px;
  display: grid;
  place-items: center;
  color: white;
}

.card::before,
.card::after {
  content: "";
  position: absolute;
  inset: -4px;
  z-index: -1;
  border-radius: 20px;
  background: conic-gradient(from var(--angle),
    #ff0080, #7928ca, #00d4ff, #ff0080);
  animation: spin 3s linear infinite;
}

@property --angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}
@keyframes spin {
  to { --angle: 360deg; }
}
